const wnbaOldPreset=historicalPreset;
historicalPreset=function(league,year){const p=wnbaOldPreset(league,year);if(league!=='wnba')return p;const r=WNBA_FINANCIAL_YEARS[year];if(!r)throw Error('Missing WNBA season');Object.assign(p.rules,wnbaSettings(r));p.cap=r.cap/1e6;p.notes=p.notes.filter(n=>!/(one-time|contract settings|Minimum\/maximum|payroll floor|Centralized contracts|pick-by-pick|four-season|Each value remains editable|cap exceptions, service)/i.test(n));p.notes.unshift('New WNBA careers use annual contract rules and historical financial progression. Existing saves require the explicit repair preview. Player salaries are simulation estimates, not individual historical deals.');p.notes.push(...r.gaps,'Early/unsupported contract rights and hardship categories are not automatically granted. Source details are included in WNBA finances.');return p};
