const wnbaOldQuote=freeAgentQuote;freeAgentQuote=function(p,t=team()){return wnbaEnabled()?wnbaMillions(wnbaDemandDollars(p,t,wnbaTransactionYear())):wnbaOldQuote(p,t)};
