function wnbaOfferContract(p,t,o,year){return wnbaMakeContract(p,t,{year,salary:wnbaDollars(o.salary),years:o.years})}
function wnbaOfferError(p,t,o,year,reserve=true){if(!p||!Number.isFinite(o.salary)||!Number.isInteger(o.years)||o.years<1||o.years>4)return 'Enter a valid whole-dollar salary and term.';if(Math.abs(o.salary*1e6-Math.round(o.salary*1e6))>.00001)return 'WNBA salaries use whole dollars.';const c=wnbaOfferContract(p,t,o,year);const errors=wnbaValidateContract(p,t,c);if(errors)return errors;const temp={...p,wnbaContract:c,contractThrough:wnbaContractEnd(c)};for(const a of c.annual){const e=wnbaValidateTransaction(t,{add:[temp],year:a.year,contracts:[{p,c}],reserve});if(e)return e;}return '';}
function wnbaFAOfferCheck(p,t,o){const f=state.freeAgency,e=faEntry(p?.id);if(!faActive()||!e||!state.free.some(q=>q.id===p.id))return 'Player is not available.';if(f.phase==='resign'&&e.former!==t.id)return 'Only the former team can negotiate in this window.';if(o.route!=='cap')return 'WNBA contracts cannot use Bird, mid-level, or minimum exceptions.';if(!Number.isInteger(o.minutes)||o.minutes<0||o.minutes>40)return 'Choose 0–40 minutes.';const held=f.pending.filter(h=>h.offer.team===t.id&&h.id!==p.id).map(h=>{const q=state.free.find(q=>q.id===h.id);return q?{...q,wnbaContract:wnbaOfferContract(q,t,h.offer,state.year+1)}:null}).filter(Boolean);return wnbaOfferError(p,{...t,roster:t.roster.concat(held)},o,state.year+1);}
function wnbaFASign(p,o){const t=state.teams[o.team],error=wnbaFAOfferCheck(p,t,o);if(error)return false;const c=wnbaOfferContract(p,t,o,state.year+1);internationalPrepareSigning(p);wnbaAssign(p,c,state.year+1);p.rotationMinutes=o.minutes;p.tradeWait=15;p.moraleAdjustment=8;t.roster.push(p);state.free=state.free.filter(q=>q.id!==p.id);const f=state.freeAgency;f.offers=f.offers.filter(q=>q.id!==p.id);faLog(t.city+' signed '+p.name+' for '+wnbaFormat(c.annual[0].base)+'; WNBA cap validated.');return true;}
function wnbaCPUOffers(){const f=state.freeAgency,year=state.year+1,r=wnbaRules(year);wnbaCPUUpgradeOffers(year,r);for(const t of state.teams.filter(t=>t.id!==controlledTeamId()||simulationAutopilot())){if(t.roster.length>=r.rosterMin)continue;let virtual={...t,roster:[...t.roster]};for(const p of [...state.free].sort((a,b)=>b.ovr-a.ovr||a.id-b.id)){if(virtual.roster.length>=r.rosterMin||f.offers.filter(o=>o.team===t.id).length>=3)break;if(f.pending.some(h=>h.id===p.id)||(f.phase==='resign'&&faEntry(p.id)?.former!==t.id))continue;const min=wnbaMinimum(p,year),remaining=Math.max(0,r.rosterMin-virtual.roster.length-1),budget=wnbaLedger(virtual,year).room-remaining*Math.max(...r.minimumTiers.map(tier=>tier[1])),salary=Math.min(wnbaMaximum(p,t,year),wnbaDemandDollars(p,t,year),budget);if(salary<min)continue;const o={id:p.id,team:t.id,salary:wnbaMillions(salary),years:1,minutes:p.ovr>=75?32:18,route:'cap'};if(wnbaOfferError(p,virtual,o,year)||wnbaFAOfferCheck(p,t,o))continue;f.offers.push(o);virtual.roster.push({...p,wnbaContract:wnbaOfferContract(p,t,o,year)});}}}
function wnbaInSeasonError(p,salary,years){if(faActive())return 'Use the offseason bidding window.';const error=wnbaOfferError(p,team(),{salary,years},state.year);if(error)return error;if(wnbaDollars(salary)<wnbaDemandDollars(p,team(),state.year))return p.name+' declined. Asking salary is '+wnbaFormat(wnbaDemandDollars(p,team(),state.year))+'.';return '';}
const wnbaOldSign=sign;sign=function(id){if(!wnbaEnabled())return wnbaOldSign(id);return negotiateFreeAgent(id)};
function wnbaDraftPick(id){const d=ensureDraft(),index=d.picks.length;if(!draftReady()||!d.order.length||index>=state.teams.length*draftRoundCount())return false;if(wnbaTransitionError())return false;const club=state.teams[draftOrder(d)[index]],at=d.prospects.findIndex(p=>p.id===id);if(at<0)return false;const p=d.prospects.splice(at,1)[0],round=Math.floor(index/state.teams.length)+1,slot=index%state.teams.length+1;Object.assign(p.bio,{draftYear:state.year,draftRound:round,draftPick:index+1,draftTeam:club.abbr,debutYear:state.year+1});p.wnbaService={seasons:0,asOf:state.year+1,evidence:'generated_draft'};wnbaAssign(p,wnbaMakeContract(p,club,{kind:'rookie',year:state.year+1,round,pick:slot}),state.year+1);p.rotationMinutes=0;p.tradeWait=15;d.picks.push({number:index+1,round,team:club.id,id:p.id,name:p.name,pos:p.pos,ovr:p.ovr,pot:p.pot});const stashed=internationalOnDraft(p);if(!stashed&&!wnbaValidateTransaction(club,{add:[p],contracts:[{p,c:p.wnbaContract}],year:state.year+1,reserve:true})){internationalPrepareSigning(p);club.roster.push(p)}else(state.draftRights??=[]).push({team:club.id,player:p});say(club.city+' selects '+p.name+'.'+(club.roster.includes(p)?' Rookie scale signed.':' Unsigned rights retained; cap/roster or overseas commitment.'));return true;}
function wnbaTryRights(r){const p=r.player,t=state.teams[r.team],year=wnbaTransactionYear();if(!internationalStashReady(p))return 'Overseas commitment remains.';const c=wnbaMakeContract(p,t,{kind:'rookie',year,round:p.bio.draftRound,pick:(p.bio.draftPick-1)%state.teams.length+1}),q={...p,wnbaContract:c};const e=wnbaValidateTransaction(t,{add:[q],contracts:[{p,c}],year,reserve:true});if(e)return e;internationalPrepareSigning(p);p.wnbaService={seasons:0,asOf:year,evidence:'first_rookie_signing'};wnbaAssign(p,c,year);p.tradeWait=15;t.roster.push(p);state.draftRights=state.draftRights.filter(x=>x!==r);return '';}
async function wnbaSignRights(id){if(!ownerCanManage())return;const r=state.draftRights?.find(r=>r.player.id===id&&r.team===controlledTeamId());if(!r)return;const before=snapshotState(),error=wnbaTryRights(r);if(error)return toast(error);await draftCommit(before);}
function wnbaCPURights(){for(const r of [...(state.draftRights||[])])if(r.team!==controlledTeamId()||simulationAutopilot())wnbaTryRights(r);}
const wnbaOldRookieSalary=rookieContractSalary;rookieContractSalary=function(index,round,rounds){return wnbaEnabled()?wnbaMillions(wnbaRookieSchedule(wnbaTransactionYear(),round,index%state.teams.length+1).salaries[0]):wnbaOldRookieSalary(index,round,rounds)};
function wnbaTradeLegality(a,b,out,into,cash,outPicks,inPicks){const errors=[];if(a.id===b.id||expansionPendingSeason(a)||expansionPendingSeason(b))errors.push('Choose two active teams.');if(tradeDeadlinePassed())errors.push('Trade deadline has passed.');if(cash!==0)errors.push('WNBA trades cannot include cash or retained salary.');for(const [t,give,get,picks] of [[a,out,into,outPicks],[b,into,out,inPicks]]){if(new Set(give.map(p=>p.id)).size!==give.length||give.some(p=>!t.roster.includes(p)))errors.push('A player is no longer on the sending roster.');for(const p of give){if(tradeRestrictionText(p))errors.push(p.name+': '+tradeRestrictionText(p));}if(t.roster.length-give.length+get.length<wnbaRules().rosterMin)errors.push(t.city+' must retain the minimum roster.');const e=wnbaValidateTransaction(t,{remove:give.map(p=>p.id),add:get,year:wnbaTransactionYear()});if(e)errors.push(t.city+': '+e);const keys=new Set(tradePicks(t).map(tradePickKey));if(new Set(picks.map(tradePickKey)).size!==picks.length||picks.some(p=>!keys.has(tradePickKey(p))))errors.push('Draft pick unavailable.');}return [...new Set(errors)];}
function wnbaExtensionError(p,years){const c=p.wnbaContract,r=wnbaRules(),year=state.year;if(r.year<2008)return 'Early extension rules are undocumented; use free agency at contract expiration.';if(!c)return 'Contract metadata is missing; use free agency.';if(c.kind==='rookie'){const option=c.annual[3],window=r.year>=2026?0:14;if(c.extendedYear||state.year!==c.startYear+3||state.day>window||option?.option!=='exercised')return 'Rookie extensions require an exercised fourth-year option and the preseason window following the third season (May 1 / May 15 deadline).';return Number.isInteger(years)&&years>=1&&years<=3?'':'Rookie extensions may add one to three seasons.';}if(c.annual.length<2||year<=c.signedYear||Number.isInteger(c.signedStamp)&&medicalStamp()<c.signedStamp+365||c.extendedYear&&year<=c.extendedYear)return 'Veteran extensions require a 2–4-year contract and its first anniversary.';const remaining=wnbaContractEnd(c)-year+1;if(!Number.isInteger(years)||years<1||remaining+years>wnbaTermLimit(p,team(),year))return 'The extension exceeds the total contract term allowed from signing.';return '';}
const wnbaOldExtensionQuote=extensionQuote;extensionQuote=function(p){if(!wnbaEnabled())return wnbaOldExtensionQuote(p);const old=p.wnbaContract?.annual.filter(a=>a.option!=='declined').at(-1)?.base??wnbaDollars(p.salary),year=(p.contractThrough??state.year)+1,r=wnbaRules();return wnbaMillions(Math.max(wnbaMinimum(p,year),Math.min(wnbaDemandDollars(p,team(),year),p.wnbaContract?.kind==='rookie'?Infinity:Math.floor(old*(r.extensionFirstYearFactor||1)),p.wnbaContract?.kind==='rookie'?(wnbaRules(year).specialMaximum||wnbaRules(year).ordinaryMaximum):wnbaMaximum(p,team(),year))));};
const wnbaOldExtensionDialog=extendPlayerContract;extendPlayerContract=function(id){if(!wnbaEnabled())return wnbaOldExtensionDialog(id);const p=team().roster.find(p=>p.id===id);if(!p)return;const error=negotiationStatus(p).refuses?(negotiationStatus(p).reason||'Player is declining extension discussions.'):wnbaExtensionError(p,1);titleModal('WNBA contract extension',error?'<p>'+escapeHTML(error)+'</p>':`<p>${escapeHTML(p.name)} · New annual salary ${money(extensionQuote(p))}, beginning ${p.contractThrough+1}. Existing years stay unchanged.</p><form onsubmit="confirmContractExtension(event,${id})"><label>Additional years<input name="years" type="number" min="1" max="3" value="1"></label><p id="extension-error" role="alert"></p><button>Validate and sign extension</button></form>`);};
const wnbaOldConfirmExtension=confirmContractExtension;confirmContractExtension=async function(event,id){if(!wnbaEnabled())return wnbaOldConfirmExtension(event,id);event.preventDefault();if(!ownerCanManage())return;const p=team().roster.find(p=>p.id===id);if(!p)return;const years=Number(event.target.elements.years.value),el=document.getElementById('extension-error'),e=negotiationStatus(p).refuses?(negotiationStatus(p).reason||'Player is declining extension discussions.'):wnbaExtensionError(p,years);if(e){el.textContent=e;return;}const before=snapshotState(),c=copy(p.wnbaContract),salary=wnbaDollars(extensionQuote(p)),start=p.contractThrough+1;for(let i=0;i<years;i++)c.annual.push({year:start+i,base:salary,guaranteed:0,option:null});c.extendedYear=state.year;c.extensionStart=start;const q={...p,wnbaContract:c};for(let y=start;y<start+years;y++){const error=wnbaValidateTransaction(team(),{remove:[p.id],add:[q],year:y,reserve:true});if(error){el.textContent=error;return;}}wnbaAssign(p,c);if(await save()===false){state=before;el.textContent='Could not save extension.';return;}closeTitleModal();render();};
const wnbaOldRelease=releasePlayer;releasePlayer=async function(id){if(!wnbaEnabled())return wnbaOldRelease(id);const p=team().roster.find(p=>p.id===id);if(!p||!ownerCanManage())return;if(injuryDays(p)>0)return toast('Injury salary protection requires review; an injured WNBA player cannot be waived through this simplified release flow.');if(p.wnbaContract?.hardship)return toast('Emergency replacements terminate when their authorization ends.');if(team().roster.length<=wnbaRules().rosterMin)return toast('Keep the minimum roster.');const elapsed=Math.min(1,state.day/Math.max(1,state.schedule.length)),obligations=[];for(const a of p.wnbaContract?.annual||[{year:state.year,base:wnbaDollars(p.salary),guaranteed:wnbaDollars(p.salary)}]){if(a.year<state.year||a.option==='pending'||a.option==='declined')continue;const earned=a.year===state.year?Math.ceil(a.base*elapsed):0,midpoint=a.year===state.year&&elapsed>=.5?a.base:0,amount=Math.max(a.guaranteed,earned,midpoint);if(amount)obligations.push({team:controlledTeamId(),id:p.id,name:p.name,year:a.year,amount,reason:'Waived salary obligation'});}if(!confirm('Release '+p.name+'? '+wnbaFormat(obligations.reduce((n,d)=>n+d.amount,0))+' in earned/protected salary remains owed.'))return;const before=snapshotState();state.wnbaFinance.dead.push(...obligations);team().roster=team().roster.filter(q=>q.id!==id);delete p.wnbaContract;delete p.contractThrough;p.salary=freeAgentQuote(p);state.free.push(p);if(await save()===false){state=before;return toast('Release could not be saved.');}render();};
const wnbaOldNewSeason=newSeason;newSeason=function(...args){if(wnbaEnabled()){const error=wnbaTransitionError();if(error)return toast(error);for(const t of state.teams){const r=wnbaRules(state.year+1),l=wnbaLedger(t,state.year+1);if(l.total>r.cap||t.roster.length<r.rosterMin||t.roster.length>r.rosterMax)return toast('Season transition blocked: '+t.city+' needs a legal roster and cap payroll. Existing contracts are preserved.');}}return wnbaOldNewSeason(...args)};
function wnbaRulesPanel(r,year=r.year){return `<section class="panel note"><h3>WNBA financial season · ${r.year}${year>2026?' (2026 fallback; future amounts unverified)':''}</h3><p>${r.capEvidence==='simulation_estimate'?'Estimated simulation team budget (not a documented historical cap)':'Hard salary cap'}: ${wnbaFormat(r.cap)}. Ordinary maximum ${wnbaFormat(r.ordinaryMaximum)} (${r.maximumEvidence.replaceAll('_',' ')}). ${r.specialMaximum?'Eligible maximum '+wnbaFormat(r.specialMaximum)+' requires documented service and qualifying team continuity; ratings alone do not qualify.':''}</p><p>Minimum tiers: ${r.minimumTiers.map(([service,amount])=>service+'+ years: '+wnbaFormat(amount)).join(' · ')}. Displayed settings use the lowest minimum and ordinary maximum. Inputs marked $M use millions: $30,000 = 0.03.</p><p>Generated player contracts are simulation estimates; verified rookie scales identify their entry cohort. No individual historical deals are asserted.</p>${r.gaps.map(g=>'<p class="muted">'+escapeHTML(g)+'</p>').join('')}<details><summary>Financial sources and limitations</summary>${r.sources.map(k=>'<p><a href="'+WNBA_FINANCIAL_SOURCES[k].url+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(WNBA_FINANCIAL_SOURCES[k].location)+'</a></p>').join('')}<p>Early terms, service thresholds and rookie scales with missing documentation use labeled conservative simulation rules. Daily earned-pay proration uses the game calendar. Qualifying-offer holds, grievance settlements, special suspensions, injury salary protection, developmental deals, EPIC, and ordinary-hardship medical approval are not fully modeled; no automatic cap relief is granted. Team minimum is a season-end payment obligation, not a signing minimum. Business revenue and coach budgets retain the existing game model.</p></details></section>`}
const wnbaOldSettingsMarkup=leagueSettingsMarkup;leagueSettingsMarkup=function(rules=leagueRules(),year=state.year,lock=leagueSettingLock,groups=LEAGUE_SETTING_GROUPS,capAmount=salaryCap()){let html=wnbaOldSettingsMarkup(rules,year,lock,groups,capAmount);if(rules.historicalSource==='wnba'){const r=WNBA_FINANCIAL_YEARS[wnbaEnabled()&&!onSetup?wnbaRules().year:rules.historicalYear];if(r)html=wnbaRulesPanel(r,year)+html;if(wnbaEnabled()&&!onSetup)html+='<p>WNBA financial fields follow the central registry. Use the progression control in Finances; changing the historical reference does not rewrite signed contracts.</p>';else if(!onSetup)html+='<p>Legacy WNBA save: signed contracts are unchanged. <button type="button" onclick="showWNBARepair()">Preview contract repair</button></p>';}return html;};
const wnbaOldReadSettingsForm=readLeagueSettingsForm;readLeagueSettingsForm=function(v){const next=wnbaOldReadSettingsForm(v);if(wnbaEnabled()&&!onSetup){const rules=wnbaSettings(wnbaRules());for(const k of Object.keys(rules))if(next[k]!==rules[k])throw Error('WNBA financial rules are centrally managed. Use Financial Progression in Finances.');if(v.cap!==undefined&&wnbaDollars(Number(v.cap))!==wnbaRules().cap)throw Error('WNBA cap follows the selected financial season.');if(next.historicalSource!=='wnba')throw Error('This career uses WNBA contract rules; changing player gender does not change league identity.');}return next;};
const wnbaOldFinancesView=financesView;financesView=function(){if(!wnbaEnabled())return (wnbaHistorical()?'<section class="panel note"><h3>Historical WNBA contract repair available</h3><p>This legacy career may contain NBA-scale contracts. Preview changes and create a complete backup before applying a repair.</p><button onclick="showWNBARepair()">Preview contract repair</button></section>':'')+wnbaOldFinancesView();const l=wnbaLedger(team()),next=wnbaLedger(team(),state.year+1),r=wnbaRules();return `<div class="finance-page">${wnbaRulesPanel(r,state.year)}<section class="finance-summary">${[['Current cap / budget',l.cap],['Current cap payroll',l.total],['Available cap space',l.room],['Guaranteed active salary (subset)',l.guaranteed],['Dead money',l.dead],['Next-season committed payroll',next.total]].map(([title,v])=>'<article class="finance-metric"><small>'+title+'</small><strong>'+wnbaFormat(v)+'</strong></article>').join('')}</section><section class="panel note"><h3>Historical Financial Progression</h3><p>${state.wnbaFinance.progression?'Enabled: new transactions resolve the applicable calendar year.':'Disabled: '+state.wnbaFinance.baseYear+' financial environment is frozen.'} Existing signed annual schedules remain intact, subject to documented minimum adjustments. Future cap conflicts block new spending; they do not erase contracts.</p><button onclick="toggleWNBAProgression()">${state.wnbaFinance.progression?'Freeze current environment':'Enable annual historical progression'}</button><h3>Exceptions</h3><p>No NBA soft-cap, Bird, MLE or luxury-tax exceptions. Unsupported WNBA exceptions cannot be used to bypass the cap.</p><button onclick="wnbaHardshipDialog()">Check emergency hardship eligibility</button>${(state.wnbaFinance.hardships||[]).map(g=>'<p>'+escapeHTML(g.reason)+' · '+(g.active?'Active':'Terminated')+' · '+wnbaFormat(g.amount)+' authorized replacement</p>').join('')}<h3>Waived obligations</h3>${state.wnbaFinance.dead.filter(d=>d.team===controlledTeamId()&&d.year>=state.year).map(d=>'<p>'+escapeHTML(d.name)+' · '+d.year+' · '+wnbaFormat(d.amount)+'</p>').join('')||'<p>No modeled waived obligations.</p>'}<p>Minimum team salary ${r.teamMinimum?wnbaFormat(r.teamMinimum)+'; any shortfall is paid at season end.':'not documented for this season.'}</p></section></div>`;};
async function toggleWNBAProgression(){if(!wnbaEnabled()||settingsBusy)return;const before=snapshotState();state.wnbaFinance.progression=!state.wnbaFinance.progression;if(!state.wnbaFinance.progression)state.wnbaFinance.baseYear=state.wnbaFinance.financialYear;wnbaApplySettings(state);if(await save()===false){state=before;return toast('Could not save progression preference.');}render();}
const wnbaOldFAView=freeAgencyView;freeAgencyView=function(){if(!wnbaEnabled())return wnbaOldFAView();if(!faActive())return '<section class="panel note"><h2>WNBA free agency</h2><p>All offers use the applicable season’s contract rules and hard cap.</p>'+(draftComplete()?'<button onclick="'+(state.freeAgency?.phase==='complete'?'newSeason()':'beginFreeAgency()')+'">'+(state.freeAgency?.phase==='complete'?'Start next season':'Begin re-signing period')+'</button>':'')+'</section>'+faMarketTable(state.free);const f=state.freeAgency,r=wnbaRules(state.year+1);return `<section class="panel note"><h2>WNBA ${state.year+1} · ${f.phase==='resign'?'Re-signing':'Open market'} · Round ${f.round}</h2><p>Team cap ${wnbaFormat(r.cap)} · Next-season payroll ${money(faPayroll(team()))} · No NBA exceptions</p><button onclick="advanceFreeAgency()">Advance negotiation round</button> ${f.phase==='market'?'<button onclick="finishFreeAgency()">Finish free agency</button>':''}${f.pending.filter(s=>s.former===controlledTeamId()).map(s=>'<p>'+escapeHTML(state.free.find(p=>p.id===s.id)?.name||'Player')+' offer sheet <button onclick="matchFreeAgent('+s.id+',true)">Match</button> <button onclick="matchFreeAgent('+s.id+',false)">Decline</button></p>').join('')}</section>${faMarketTable(state.free.filter(p=>f.phase==='market'||faEntry(p.id)?.former===controlledTeamId()))}<section class="panel note">${f.log.slice(0,20).map(s=>'<p>'+escapeHTML(s)+'</p>').join('')}</section>`;};
const wnbaOldFADialog=faOfferDialog;faOfferDialog=function(id){if(!wnbaEnabled())return wnbaOldFADialog(id);const p=state.free.find(p=>p.id===id);if(!p)return;const y=state.year+1,minimum=wnbaMinimum(p,y),maximum=wnbaMaximum(p,team(),y);titleModal('WNBA offer · '+escapeHTML(p.name),`<p>Financial year ${wnbaRules(y).year}; minimum ${wnbaFormat(minimum)}, eligible maximum ${wnbaFormat(maximum)}. Amounts below are $M.</p><form onsubmit="submitFreeAgentOffer(event,${id})"><label>Annual salary ($M)<input name="salary" type="number" step="0.000001" min="${minimum/1e6}" max="${maximum/1e6}" value="${faEntry(id)?.demand??freeAgentQuote(p)}"></label><label>Years<input name="years" type="number" min="1" max="${wnbaTermLimit(p,team(),y)}" value="1"></label><label>Minutes<input name="minutes" type="number" min="0" max="40" value="24"></label><input name="route" type="hidden" value="cap"><p id="fa-offer-error" role="alert"></p><button>Submit offer</button></form>`);};
const wnbaOldPlayerContract=playerContract;playerContract=function(ctx){if(!wnbaEnabled())return wnbaOldPlayerContract(ctx);const {p,club,own}=ctx,c=p.wnbaContract;return playerCard('WNBA CONTRACT',c?'<p>'+escapeHTML(c.evidence.replaceAll('_',' '))+' · Financial rules '+c.ruleYear+' · '+escapeHTML(c.kind)+'</p><table><thead><tr><th>Year</th><th>Salary</th><th>Guarantee</th><th>Option</th></tr></thead><tbody>'+c.annual.map(a=>'<tr><td>'+a.year+'</td><td>'+wnbaFormat(a.base)+'</td><td>'+wnbaFormat(a.guaranteed)+'</td><td>'+(a.option||'—')+'</td></tr>').join('')+'</tbody></table>'+(own?'<button onclick="extendPlayerContract('+p.id+')">Extension eligibility</button>':'')+(own&&c.annual.some(a=>a.option==='pending')?'<button onclick="wnbaRookieOption('+p.id+',true)">Exercise rookie option</button> <button onclick="wnbaRookieOption('+p.id+',false)">Decline rookie option</button>':''):'<p>Free-agent demand '+money(freeAgentQuote(p))+'. Estimated market value, subject to individual and team limits.</p>');};
async function wnbaRookieOption(id,exercise){const p=team().roster.find(p=>p.id===id),c=p?.wnbaContract,a=c?.annual.find(a=>a.option==='pending');if(!a||!ownerCanManage())return;const deadline=c.startYear+2;if(state.year!==deadline||state.day>0)return toast('Exercise/decline at the preseason following the second season. This game uses a conservative preseason deadline.');const before=snapshotState();a.option=exercise?'exercised':'declined';if(exercise){a.guaranteed=a.base;if(c.ruleYear>=2026)c.annual[2].guaranteed=c.annual[2].base;}p.contractThrough=wnbaContractEnd(c);if(exercise){const error=wnbaValidateTransaction(team(),{year:a.year,reserve:true});if(error){state=before;return toast(error);}}if(await save()===false){state=before;return toast('Option could not be saved.');}render();profile(id);}
/* Emergency hardship only where the retrieved CBA establishes the <10 able rule.
 * Ordinary hardship requires external medical approval not represented by game data;
 * it is never inferred from insufficient cap room. */
function wnbaEmergencyEligibility(t){const r=wnbaRules();if(!(r.year===2008||r.year>=2014))return 'This season’s emergency hardship threshold is not verified in the implemented rules.';if(state.day>=state.schedule.length)return 'Emergency hardship is available only during the regular season.';const able=t.roster.filter(p=>injuryDays(p)===0&&!p.wnbaContract?.hardship).length;if(able>=10)return 'Emergency hardship requires fewer than 10 able regular players; lacking cap space is not eligibility.';if((state.wnbaFinance.hardships||[]).some(g=>g.team===t.id&&g.active))return 'An emergency replacement is already active.';return '';}
function wnbaHardshipDialog(){const error=wnbaEmergencyEligibility(team());titleModal('Emergency hardship',error?'<p>'+escapeHTML(error)+'</p>':'<p>Fewer than 10 regular players are able to play. The game can authorize one unprotected emergency replacement until 10 other players are available. Its salary still appears in payroll, with a separate authorized overage.</p>'+state.free.slice().sort((a,b)=>a.ovr-b.ovr).slice(0,12).map(p=>'<p>'+escapeHTML(p.name)+' <button onclick="wnbaSignEmergency('+p.id+')">Approve replacement</button></p>').join(''));}
async function wnbaSignEmergency(id){if(!ownerCanManage())return;const p=state.free.find(p=>p.id===id),t=team(),error=wnbaEmergencyEligibility(t);if(error||!p)return toast(error||'Player unavailable.');const before=snapshotState(),r=wnbaRules(),fraction=(state.schedule.length-state.day)/state.schedule.length,amount=Math.ceil(wnbaMinimum(p)* (r.year>=2026?1:.75)*fraction),c=wnbaMakeContract(p,t,{salary:amount,years:1,evidence:'emergency_hardship_simulation'});c.hardship={type:'emergency',approvedYear:state.year,approvedDay:state.day,terminateWhenAble:10};const grant={id:'emergency-'+state.year+'-'+state.day+'-'+p.id,team:t.id,playerId:p.id,year:state.year,amount,active:true,reason:'Emergency hardship: '+t.roster.filter(q=>!injuryDays(q)).length+' able regular players; Article VII Section 4',approvedDay:state.day,expiresYear:state.year};(state.wnbaFinance.hardships??=[]).push(grant);wnbaAssign(p,c);const e=wnbaValidateTransaction(t,{add:[p],year:state.year});if(e){state=before;return toast(e);}t.roster.push(p);state.free=state.free.filter(q=>q.id!==p.id);if(await save()===false){state=before;return toast('Could not save replacement.');}closeTitleModal();render();}
function wnbaExpireHardships(){if(!wnbaEnabled())return;for(const g of state.wnbaFinance.hardships||[]){if(!g.active)continue;const t=state.teams[g.team],p=t?.roster.find(p=>p.id===g.playerId);if(!p){g.active=false;continue;}const able=t.roster.filter(q=>q.id!==g.playerId&&!q.wnbaContract?.hardship&&!injuryDays(q)).length;if(able<10&&g.year===state.year&&state.day<state.schedule.length)continue;const elapsed=Math.max(0,Math.min(1,(state.day-g.approvedDay)/Math.max(1,state.schedule.length-g.approvedDay))),owed=Math.ceil(g.amount*elapsed);if(owed)state.wnbaFinance.dead.push({team:t.id,id:p.id,name:p.name,year:g.year,amount:owed,reason:'Earned emergency replacement salary',hardshipId:g.id});g.active=false;g.earned=owed;t.roster=t.roster.filter(q=>q.id!==p.id);delete p.wnbaContract;delete p.contractThrough;state.free.push(p);}}
const wnbaOldOwnerDay=ownerDay;ownerDay=function(...args){wnbaVestRookieGuarantees();wnbaExpireHardships();return wnbaOldOwnerDay(...args)};

function wnbaVestRookieGuarantees(){if(!wnbaEnabled()||state.day<1)return;for(const t of state.teams)for(const p of t.roster){const c=p.wnbaContract;if(c?.kind!=='rookie'||c.ruleYear<2026)continue;const a=wnbaAnnual(p,state.year);if(a&&(state.year===c.startYear+1||state.year===c.startYear&&c.round===1))a.guaranteed=a.base;}}
const wnbaOldNegotiation=negotiateFreeAgent;negotiateFreeAgent=function(id){if(!wnbaEnabled())return wnbaOldNegotiation(id);if(faBusy||!ownerCanManage())return;if(faActive())return faOfferDialog(id);const p=state.free.find(p=>p.id===id);if(!p)return;const min=wnbaMinimum(p),max=wnbaMaximum(p,team());titleModal('WNBA offer · '+escapeHTML(p.name),`<p>Financial season ${wnbaRules().year} · Service ${wnbaService(p)} years · Eligible salary range ${wnbaFormat(min)}–${wnbaFormat(max)}. Asking ${money(freeAgentQuote(p))}.</p><form onsubmit="submitInSeasonOffer(event,${id})"><label>Annual salary ($M)<input name="salary" type="number" min="${min/1e6}" max="${max/1e6}" step="0.000001" value="${freeAgentQuote(p)}" required></label><label>Seasons<input name="years" type="number" min="1" max="${wnbaTermLimit(p,team(),state.year)}" value="1" required></label><p>The current season counts as year one. Individual eligibility and hard-cap room are checked before signing.</p><p id="fa-offer-error" role="alert"></p><button>Validate and submit offer</button></form>`);};

// Teams at or above the minimum still bid on a clearly better free agent when a roster spot is open.
// (WNBA releases leave protected salary on a hard cap, so full rosters do not swap here.)
function wnbaCPUUpgradeOffers(year,r){const f=state.freeAgency;for(const t of state.teams.filter(t=>t.id!==controlledTeamId()||simulationAutopilot())){if(t.roster.length<r.rosterMin||t.roster.length>=r.rosterMax||f.offers.some(o=>o.team===t.id&&o.upgrade))continue;const weakest=Math.min(...t.roster.map(p=>p.ovr));
 for(const p of state.free.filter(p=>p.ovr>=Math.max(75,weakest+5)&&!f.pending.some(h=>h.id===p.id)&&(f.phase==='market'||faEntry(p.id)?.former===t.id)&&!f.offers.some(o=>o.id===p.id&&o.team===t.id)).sort((a,b)=>b.ovr-a.ovr||a.id-b.id)){const min=wnbaMinimum(p,year),salary=Math.min(wnbaMaximum(p,t,year),wnbaDemandDollars(p,t,year),wnbaLedger(t,year).room);if(salary<min)continue;const o={id:p.id,team:t.id,salary:wnbaMillions(salary),years:1,minutes:32,route:'cap',upgrade:true};if(wnbaOfferError(p,t,o,year)||wnbaFAOfferCheck(p,t,o))continue;f.offers.push(o);break}}}
